<template>
  <div class="space-y-6">
    <PageHeader title="出站" parent="代理" description="选择直连、阻断、外部代理或内部节点中转，入口协议与下一跳协议独立。"><template #actions><button @click="openCreate" class="ios-btn-primary">创建出站</button><button @click="revision" :disabled="!nodeId" class="ios-btn-secondary disabled:opacity-40">生成节点配置版本</button></template></PageHeader>
    <label class="text-sm">所属节点<select v-model="nodeId" @change="page = 1; load()" class="form-input-base mt-2"><option value="">全部节点</option><option v-for="node in nodes" :key="node.id" :value="node.id">{{ node.name }}</option></select></label>
    <ErrorState v-if="error" :message="error" @retry="load" /><EmptyState v-else-if="!outbounds.length" title="暂无自定义出站" description="每个节点默认具有 Direct 与 Block，其他出站可在此创建。" />
    <DataTable v-else><template #header><th>名称</th><th>节点</th><th>协议</th><th>目标</th><th>TCP / UDP</th><th>状态 / 探测</th><th>操作</th></template><template #body><tr v-for="outbound in outbounds" :key="outbound.id"><td class="p-4 font-semibold">{{ outbound.name }}</td><td>{{ nodes.find(node => node.id === outbound.nodeId)?.name || outbound.nodeId }}</td><td>{{ outbound.protocol }}</td><td class="text-xs">{{ outbound.targetNodeId ? nodes.find(node => node.id === outbound.targetNodeId)?.name || outbound.targetNodeId : outbound.address || '本地' }}<p>{{ outbound.port || '—' }} · {{ outbound.targetInboundId ? '内部中转' : '外部或本地出站' }}</p></td><td class="text-xs"><p v-if="outbound.wireGuardPublicKey" class="max-w-48 break-all font-mono" :title="outbound.wireGuardPublicKey">公钥：{{ outbound.wireGuardPublicKey }}</p>{{ outbound.supportTcp ? 'TCP' : '—' }} / {{ outbound.supportUdp ? 'UDP' : '—' }}</td><td><StatusBadge :status="outbound.enabled ? 'active' : 'disabled'" /><p class="text-xs text-gray-500 mt-2">{{ healthLabel(outbound, outbound.probeInterval) }}</p></td><td class="space-x-2"><button @click="openEdit(outbound)" class="ios-action-btn-primary">编辑</button><button @click="target = outbound; confirmVisible = true" class="ios-action-btn-danger">删除</button></td></tr></template><template #footer><Pagination :total="total" :current-page="page" :page-size="20" @update:page="changePage" /></template></DataTable>
    <FormDrawer v-model="drawer" :title="editing ? '编辑出站' : '创建出站'" :loading="saving" @confirm="save" confirm-text="保存草稿">
      <div class="space-y-4 text-sm">
        <label class="block">名称<input v-model="form.name" maxlength="40" class="form-input-base mt-2" /></label><label class="block">所属节点<select v-model="form.nodeId" :disabled="!!editing" class="form-input-base mt-2"><option value="">请选择</option><option v-for="node in nodes" :key="node.id" :value="node.id">{{ node.name }}</option></select></label>
        <label class="block">协议<select v-model="form.protocol" :disabled="!!editing" @change="protocolChanged" class="form-input-base mt-2"><option v-for="protocol in protocolOptions.outbound" :key="protocol">{{ protocol }}</option></select></label>
        <template v-if="!['direct', 'block'].includes(form.protocol)">
          <label class="block">连接方式<select v-model="mode" :disabled="!!editing" class="form-input-base mt-2"><option value="external">外部代理</option><option value="relay">内部节点中转</option></select></label>
          <label v-if="mode === 'relay'" class="block">目标内部入站<select v-model="form.targetInboundId" :disabled="!!editing" class="form-input-base mt-2"><option value="">请选择</option><option v-for="inbound in relayTargets" :key="inbound.id" :value="inbound.id">{{ nodes.find(node => node.id === inbound.nodeId)?.name }} · {{ inbound.name }} :{{ inbound.port }}</option></select></label>
          <template v-else>
            <label class="block">目标地址<input v-model="form.address" class="form-input-base mt-2" /></label><label class="block">目标端口<input v-model.number="form.port" type="number" min="1" max="65535" class="form-input-base mt-2" /></label>
            <label v-if="['http','socks5','tuic'].includes(form.protocol)" class="block">{{ form.protocol === 'tuic' ? 'TUIC UUID' : '认证用户名' }}<input v-model="form.username" autocomplete="off" class="form-input-base mt-2" /></label><label v-if="form.protocol !== 'wireguard'" class="block">{{ form.protocol === 'vless' ? 'UUID' : '密码 / 密钥' }}<input v-model="form.secret" type="password" autocomplete="new-password" :placeholder="editing?.hasCredential ? '留空保留现有凭据' : ''" class="form-input-base mt-2" /></label>
            <template v-if="form.protocol !== 'wireguard'"><label class="block">安全方式<select v-model="form.settings.security" class="form-input-base mt-2"><option v-if="!['trojan','hysteria2','tuic'].includes(form.protocol)" value="none">None</option><option value="tls">TLS</option></select></label><label v-if="form.settings.security === 'tls'" class="block">TLS 服务器名称<input v-model="form.settings.server_name" class="form-input-base mt-2" /></label><label v-if="form.settings.security === 'tls'" class="block">自有 CA PEM（可选）<textarea v-model="form.settings.trusted_ca_pem" rows="3" class="form-input-base mt-2 font-mono text-xs"></textarea></label><label v-if="form.protocol === 'shadowsocks'" class="block">加密方式<select v-model="form.settings.method" class="form-input-base mt-2"><option>chacha20-ietf-poly1305</option><option>aes-256-gcm</option><option>aes-128-gcm</option></select></label></template>
            <template v-else><label class="block">本地隧道地址<textarea v-model="wgAddress" rows="3" placeholder="10.77.0.2/32&#10;fd77::2/128" class="form-input-base mt-2 font-mono"></textarea></label><p class="text-xs text-gray-500">每行一个 IPv4 或 IPv6 地址，可同时填写双栈地址。</p><label class="block">本地私钥<input v-model="wgSecret" type="password" autocomplete="new-password" :placeholder="editing?.hasWireGuardKey ? '留空保留现有私钥' : '留空由系统生成'" class="form-input-base mt-2" /></label><label class="block">首个 peer 公钥<input v-model="wgPublic" class="form-input-base mt-2" /></label><p v-if="(form.settings.wireguard?.peers.length || 0) > 1" class="text-xs text-gray-500">其他 peer 将保留现有设置。</p></template>
          </template>
            <template v-if="form.settings.quic"><p class="text-xs text-gray-500">原生 QUIC，必须校验 TLS 服务器证书。</p><template v-if="form.protocol === 'hysteria2'"><label class="block">上传 Mbps<input v-model.number="form.settings.quic.up_mbps" type="number" min="0" max="100000" class="form-input-base mt-2" /></label><label class="block">下载 Mbps<input v-model.number="form.settings.quic.down_mbps" type="number" min="0" max="100000" class="form-input-base mt-2" /></label></template><template v-if="form.protocol === 'tuic'"><label class="block">拥塞控制<select v-model="form.settings.quic.congestion_control" class="form-input-base mt-2"><option value="">默认</option><option value="cubic">cubic</option><option value="new_reno">new_reno</option><option value="bbr">bbr</option></select></label><label class="block">UDP 中转模式<select v-model="form.settings.quic.udp_relay_mode" class="form-input-base mt-2"><option value="">默认</option><option value="native">native</option><option value="quic">quic</option></select></label></template></template>
          <div class="flex gap-4"><label><input v-model="form.supportTcp" type="checkbox" /> TCP</label><label v-if="form.protocol !== 'http'"><input v-model="form.supportUdp" type="checkbox" /> UDP</label></div>
          <p v-if="mode === 'relay'" class="text-xs text-gray-500">系统为此中转链路独立生成凭据。请先生成并发布目标节点配置，再发布当前节点。</p>
        </template>
        <template v-if="!['direct', 'block'].includes(form.protocol)"><label class="block">探测 URL<input v-model="form.probeUrl" class="form-input-base mt-2" /></label><label class="block">探测间隔（秒）<input v-model.number="form.probeInterval" type="number" min="3" max="300" class="form-input-base mt-2" /></label><label class="block">连接不可用时<select v-model="form.failurePolicy" class="form-input-base mt-2"><option value="Block">阻断</option><option value="Direct">直连</option><option value="BackupOutbound">备用出站</option><option value="BackupOutboundGroup">备用出口组</option><option value="BackupProxyChain">备用代理链</option></select></label><label v-if="form.failurePolicy.startsWith('Backup')" class="block">备用目标<select v-model="form.backupOutboundId" class="form-input-base mt-2"><option value="">请选择</option><option v-for="backup in selectedBackups" :key="backup.id" :value="backup.id">{{ backup.name }}</option></select></label><p v-if="form.failurePolicy === 'Direct'" class="text-xs text-amber-700">此出站不可用时将从当前节点直连，固定出口策略建议使用阻断或备用出口。</p></template><label class="block"><input v-model="form.enabled" type="checkbox" /> 启用</label>
      </div>
    </FormDrawer>
    <ConfirmDialog v-model="confirmVisible" title="删除出站草稿" :message="`删除 ${target?.name || ''}？被入站默认引用的出站不能删除，运行配置需重新发布。`" @confirm="remove" />
  </div>
</template>
<script setup lang="ts">
import { ref, reactive, computed, onMounted, watch } from 'vue'; import { useRouter } from 'vue-router'; import { proxyAPI, protocolOptions, loadProtocolSupport, type Outbound, type OutboundInput, type Inbound, type OutboundGroup, type ProxyChain, choices, healthLabel, failureNames } from '../api'; import { request, type Page } from '../../../app/apiClient'; import { type NodeView } from '../../nodes/api'; import { showToast } from '../../../app/api'; import PageHeader from '../../../components/PageHeader.vue'; import DataTable from '../../../components/DataTable.vue'; import StatusBadge from '../../../components/StatusBadge.vue'; import Pagination from '../../../components/Pagination.vue'; import FormDrawer from '../../../components/FormDrawer.vue'; import ConfirmDialog from '../../../components/ConfirmDialog.vue'; import ErrorState from '../../../components/ErrorState.vue'; import EmptyState from '../../../components/EmptyState.vue';
const allGroups = ref<OutboundGroup[]>([]); const allChains = ref<ProxyChain[]>([]); const allOutbounds = ref<Outbound[]>([]); const router = useRouter(); const outbounds = ref<Outbound[]>([]); const inbounds = ref<Inbound[]>([]); const nodes = ref<NodeView[]>([]); const nodeId = ref(''); const page = ref(1); const total = ref(0); const error = ref(''); const drawer = ref(false); const saving = ref(false); const editing = ref<Outbound | null>(null); const target = ref<Outbound | null>(null); const confirmVisible = ref(false); const mode = ref('external'); const wgAddress = ref('10.77.0.2/32'); const wgSecret = ref(''); const wgPublic = ref('');
function defaults(): OutboundInput { return { name: '', nodeId: nodeId.value, protocol: 'direct', address: '', port: 0, enabled: true, targetNodeId: '', targetInboundId: '', username: '', secret: '', settings: {}, supportTcp: true, supportUdp: true, failurePolicy: 'Block', backupOutboundId: '', probeUrl: 'https://www.gstatic.com/generate_204', probeInterval: 30 }; }
const form = reactive<OutboundInput>(defaults()); const selectedBackups = computed(() => form.failurePolicy === 'BackupOutboundGroup' ? allGroups.value.filter(item => item.enabled && item.nodeId === form.nodeId) : form.failurePolicy === 'BackupProxyChain' ? allChains.value.filter(item => item.enabled && item.nodeIds[0] === form.nodeId) : backupOptions.value); const backupOptions = computed(() => allOutbounds.value.filter(item => item.nodeId === form.nodeId && item.enabled && item.id !== editing.value?.id)); const relayTargets = computed(() => inbounds.value.filter(inbound => inbound.internalRelay && inbound.enabled && inbound.nodeId !== form.nodeId && inbound.protocol === form.protocol));
async function load() { try { const [result, ins, ns, outs, gs, cs] = await Promise.all([proxyAPI.outbounds(nodeId.value, page.value), proxyAPI.inbounds('', 1, 100), request<Page<NodeView>>('/nodes?page=1&pageSize=100'), choices((p,s) => proxyAPI.outbounds('',p,s)), choices((p,s) => proxyAPI.groups('',p,s)), choices((p,s) => proxyAPI.chains('',p,s))]); outbounds.value = result.items; total.value = result.total; inbounds.value = ins.items; nodes.value = ns.items; allOutbounds.value = outs; allGroups.value = gs; allChains.value = cs; error.value = ''; } catch (e) { error.value = (e as Error).message; } }
function changePage(value: number) { page.value = value; load(); } function openCreate() { editing.value = null; Object.assign(form, defaults()); mode.value = 'external'; wgAddress.value = '10.77.0.2/32'; wgSecret.value = ''; wgPublic.value = ''; drawer.value = true; }
function openEdit(outbound: Outbound) { editing.value = outbound; Object.assign(form, { name: outbound.name, nodeId: outbound.nodeId, protocol: outbound.protocol, address: outbound.address, port: outbound.port, enabled: outbound.enabled, targetNodeId: outbound.targetNodeId, targetInboundId: outbound.targetInboundId, username: '', secret: '', settings: JSON.parse(JSON.stringify(outbound.settings)), supportTcp: outbound.supportTcp, supportUdp: outbound.supportUdp, failurePolicy: outbound.failurePolicy, backupOutboundId: outbound.backupOutboundId, probeUrl: outbound.probeUrl, probeInterval: outbound.probeInterval }); mode.value = outbound.targetInboundId ? 'relay' : 'external'; wgAddress.value = outbound.settings.wireguard?.addresses.join('\n') || '10.77.0.2/32'; wgPublic.value = outbound.settings.wireguard?.peers[0]?.public_key || ''; wgSecret.value = ''; drawer.value = true; }
function protocolChanged() { form.settings = ['direct','block','wireguard'].includes(form.protocol) ? {} : { transport: ['hysteria2','tuic'].includes(form.protocol) ? 'quic' : 'tcp', quic: ['hysteria2','tuic'].includes(form.protocol) ? {} : undefined, security: ['trojan','hysteria2','tuic'].includes(form.protocol) ? 'tls' : 'none', method: form.protocol === 'shadowsocks' ? 'chacha20-ietf-poly1305' : undefined }; form.supportUdp = form.protocol !== 'http'; form.targetInboundId = ''; }
async function save() {
  if (saving.value) return;
  saving.value = true;
  try {
    const value = JSON.parse(JSON.stringify(form)) as OutboundInput;
    if (mode.value !== 'relay') { value.targetInboundId = ''; value.targetNodeId = ''; }
    if (value.protocol === 'wireguard' && mode.value === 'external') {
      const previous = value.settings.wireguard;
      const addresses = wgAddress.value.split(/\r?\n/).map(address => address.trim()).filter(Boolean);
      if (!addresses.length || addresses.length > 8) throw new Error('请填写 1～8 个隧道地址，每行一个。');
      const peers = [...(previous?.peers || [])];
      peers[0] = { ...(peers[0] || { allowed_ips: ['0.0.0.0/0', '::/0'], keep_alive: 15 }), public_key: wgPublic.value.trim(), endpoint: value.address.includes(':') ? `[${value.address}]:${value.port}` : `${value.address}:${value.port}` };
      value.settings = { wireguard: { ...previous, secret_key: wgSecret.value.trim(), addresses, peers, mtu: previous?.mtu ?? 1420 } };
    }
    if (!value.failurePolicy.startsWith('Backup')) value.backupOutboundId = '';
    await proxyAPI.saveOutbound(editing.value?.id || null, value);
    drawer.value = false;
    form.secret = ''; wgSecret.value = '';
    showToast('出站草稿已保存');
    await load();
  } catch (e) { showToast((e as Error).message, 'error'); }
  finally { saving.value = false; }
}
async function remove() { if (!target.value) return; try { await proxyAPI.deleteOutbound(target.value.id); showToast('出站已删除'); await load(); } catch (e) { showToast((e as Error).message, 'error'); } }
async function revision() { if (!nodeId.value) return; try { await proxyAPI.revision(nodeId.value, '更新节点代理出站'); await router.push('/system/revisions'); } catch (e) { showToast((e as Error).message, 'error'); } }
watch(drawer, visible => { if (!visible) { form.secret = ''; wgSecret.value = ''; } }); onMounted(() => { loadProtocolSupport(); load(); });
</script>


